return [{
  json: {
    status: "success",
    data: {
      recomendaciones: $input.item.json.output,
      worker: "recomendador_juegos"
    }
  }
}];

const err = $input.item.json.error;
return [{
  json: {
    status: "error",
    data: {
      motivo: (err && err.message) ? err.message : "Fallo interno del worker Recomendador de Juegos",
      worker: "recomendador_juegos"
    }
  }
}];
